/* eslint-disable react-hooks/exhaustive-deps */
import { useEffect, useContext, useState } from 'react'
import { Collapse, notification } from 'antd'
import WrappedFormComponent from '../components/FormDataFields'
import TableData from '../components/TableData'
import { store } from '../context/attributeContext'
import { useResetState, useGetProviderAttributes, useActiveVersionValue, useDataMappingValue } from '../hooks/useProviderDetails'
import { get, size } from 'lodash'

const { Panel } = Collapse

export default function Screen1 ({ ...props }) {
  const { type = 'add', productCode, packageCode, screenHandler = null, step2 = [], history = {}, provider = '' } = props
  const { state, dispatch } = useContext(store)
  const [functionState, setFunctionName] = useState('')
  const [dynamicFieldData, setDynamicFieldData] = useState([])
  const [{ dataMappingData, dataMappingStatus }, dataMappingRequest] = useDataMappingValue()
  const [{ providerAttributesData, providerAttributesStatus }, getProvidersDataRequest] = useGetProviderAttributes()
  const [{ activeVersionData, activeVersionStatus }, activeVersionRequest] = useActiveVersionValue()
  const [tableData, setTableData] = useState([])
  const [versionList, setVersionList] = useState([])
  const activeKey = get(state, 'showCollapsePanel')
  const [resetProviderDetailsState] = useResetState()

  useEffect(() => {
    if (dataMappingStatus === 'success') {
      dispatch({
        type: 'attribute-list-update',
        payload: get(dataMappingData, 'data.details', [])
      })
      resetProviderDetailsState(['dataMappingStatus'])
    }
    if (activeVersionStatus === 'success') {
      const functionName = get(activeVersionData, 'data.details.function_name', '')
      dispatch({
        type: 'set-function-name',
        payload: functionName
      })
      setFunctionName(functionName)
      resetProviderDetailsState(['activeVersionStatus'])
    }
    if (providerAttributesStatus === 'success') {
      const responsetableData = get(providerAttributesData, 'data.details.attributes', [])
      setTableData(responsetableData)
      resetProviderDetailsState(['providerAttributesStatus'])
    }
    if (providerAttributesStatus !== 'success' && providerAttributesStatus !== undefined) {
      notification.error({
        message: get(providerAttributesData)
      })
      resetProviderDetailsState(['providerAttributesStatus'])
    }
  }, [providerAttributesStatus, activeVersionStatus, dataMappingStatus])

  useEffect(() => {
    if (provider) {
      const providerData = JSON.parse(window.sessionStorage.getItem('provider')) || []
      const selectedProviderData = size(providerData) > 0 ? providerData.filter((item) => item.code === provider) : []
      const versionList = get(selectedProviderData, '[0].versions', [])
      setVersionList(versionList)
    }
  }, [provider])

  useEffect(() => {
    if (type === 'edit' && functionState) {
      getProvidersDataRequest({
        query: {
          provider_code: provider,
          function_name: functionState,
          product_code: productCode,
          package_code: packageCode
        }
      })
    }
  }, [functionState])

  useEffect(() => {
    dataMappingRequest({
      query: {
        productCode: productCode,
        type: 'creation,endorsement,internal'
      }
    })
    if (productCode && packageCode) {
      activeVersionRequest({
        query: {
          product_code: productCode,
          package_code: packageCode
        }
      })
    }
    if (type === 'edit') {
      dispatch({
        type: 'update-collapse',
        payload: ['1', '2']
      })
    } else {
      const functionName = get(state, 'functionName', '')
      const dyanamicFieldsData = get(state, 'apiVersionDynamicData')
      if (functionName) {
        setFunctionName(functionName)
      }
      if (dyanamicFieldsData.length > 0) {
        setDynamicFieldData(dyanamicFieldsData)
      }
    }
  }, [])

  const setcollapseHandler = () => {
    dispatch({
      type: 'update-collapse',
      payload: ['1', '2']
    })
  }
  return (
    <Collapse
      activeKey={activeKey}
    >
      <Panel header='Credential Fields' key='1'>
        <WrappedFormComponent
          type={type}
          dynamicFieldData={dynamicFieldData}
          versionList={versionList}
          functionName={functionState}
          provider={provider}
          productCode={productCode}
          packageCode={packageCode}
          collapseHandler={setcollapseHandler}
        />
      </Panel>
      <Panel header='Table Attributes' key='2'>
        <TableData
          type={type}
          step2={step2}
          screenChange={screenHandler}
          history={history}
          functionName={functionState}
          tableData={tableData}
          provider={provider}
          productCode={productCode}
          packageCode={packageCode}
        />
      </Panel>
    </Collapse>
  )
}
