import React from 'react'
import { Table, Row, Col, Spin } from 'antd'

const TableWrapper = (props) => {
  const {
    columns,
    dataSource = [],
    tableClassName = '',
    tip = 'Loading...',
    loading = false,
    tableAboveMessage = '',
    tableBelowMessage = '',
    pagination,
    rowSelection = null
  } = props
  return (
    <Row type='flex' justify='center'>
      <Col span={22}>
        <Spin spinning={loading} tip={tip}>
          {
            tableAboveMessage &&
            <h5><b>{tableAboveMessage}</b></h5>
          }
          <Table
            bordered
            rowSelection={rowSelection}
            className={tableClassName}
            columns={columns}
            dataSource={dataSource}
            pagination={pagination}
          />
          {
            tableBelowMessage &&
            <h5>{tableBelowMessage}</h5>
          }
        </Spin>
      </Col>
    </Row>
  )
}
export default TableWrapper
