import React, { useCallback, useEffect, useState } from 'react'
import { Button, Modal, Input, Switch } from 'antd'
import axios from 'axios'
import get from 'lodash/get'
import TableWrapper from '../../../components/Table'
import exportObj from '../../../../../../config/urls'
import { getHeader } from '../../../../../../helpers/utility'
import { showNotification } from '../../../../../../components/ShowNotification'
import TextEditor from '../../../../../../components/TextEditor'

const dynamicContentsUrl = exportObj.url.dynamicContentsUrl

const baseRows = [
  { key: 'description', label: 'Description', dynamicKey: 'description' },
  { key: 'benefit', label: 'Benefits', dynamicKey: 'benefit' },
  { key: 'tnc', label: 'Terms & Condition', dynamicKey: 'tnc' },
  { key: 'how_to_claim', label: 'How to Claim', dynamicKey: 'how_to_claim' }
]

const DEFAULT_MODAL_FORM = {
  displayName: '',
  keyValue: '',
  content: '',
  isActive: true,
  isCustomAdd: false
}

const ProductConfigurationSection = ({ productCode, packageCode }) => {
  const [tableData, setTableData] = useState([])
  const [loadingState, setLoadingState] = useState({ fetching: false, saving: false })
  const [editModal, setEditModal] = useState({ visible: false, currentRow: null })
  const [previewModal, setPreviewModal] = useState({ visible: false, currentRow: null, content: '' })
  const [modalForm, setModalForm] = useState(DEFAULT_MODAL_FORM)

  const setFetching = (fetching) => setLoadingState((prev) => ({ ...prev, fetching }))
  const setSaving = (saving) => setLoadingState((prev) => ({ ...prev, saving }))
  const updateModalForm = useCallback((fields) => {
    setModalForm((prev) => ({ ...prev, ...fields }))
  }, [])

  const fetchDynamicContents = useCallback(async ({ productCode, packageCode }) => {
    setFetching(true)
    try {
      const res = await axios.get(dynamicContentsUrl, {
        headers: getHeader(),
        params: { product_key: productCode, package_code: packageCode }
      })
      const items = get(res, 'data.data', [])
      const byKey = {}
      items.forEach((item) => { byKey[item.display_name] = item })

      const rows = baseRows.map((row) => {
        const apiItem = byKey[row.label]
        if (!apiItem) {
          return { ...row, content: row.label, status: 'Not Defined', isDefined: false, apiContent: '', is_active: false }
        }
        return {
          ...row,
          content: apiItem.display_name || row.label,
          status: apiItem.is_active ? 'Active' : 'Inactive',
          isDefined: true,
          apiContent: apiItem.content || '',
          is_active: apiItem.is_active,
          display_name: apiItem.display_name,
          keyValue: apiItem.key
        }
      })

      const extraRows = items
        .filter((item) => !baseRows.find((row) => row.label === item.display_name))
        .map((item) => ({
          key: item.key,
          label: item.display_name || item.key,
          dynamicKey: item.key,
          content: item.display_name || item.key,
          status: item.is_active ? 'Active' : 'Inactive',
          isDefined: true,
          apiContent: item.content || '',
          is_active: item.is_active,
          display_name: item.display_name,
          keyValue: item.key,
          isCustom: true
        }))

      setTableData([...rows, ...extraRows])
    } catch (e) {
      showNotification('error', 'Failed to fetch contents', 'Unable to load dynamic contents')
    } finally {
      setFetching(false)
    }
  }, [])

  useEffect(() => {
    fetchDynamicContents({ productCode, packageCode })
  }, [fetchDynamicContents, productCode, packageCode])

  const openEditModal = (record, isCustom = false) => {
    setEditModal({ visible: true, currentRow: record })
    updateModalForm({
      isCustomAdd: isCustom,
      displayName: record.display_name || record.label || '',
      keyValue: record.dynamicKey || record.key || '',
      content: record.apiContent || '',
      isActive: typeof record.is_active === 'boolean' ? record.is_active : true
    })
  }

  const openAddCustomModal = () => {
    setEditModal({ visible: true, currentRow: null })
    setModalForm({ ...DEFAULT_MODAL_FORM, isCustomAdd: true })
  }

  const closeEditModal = () => setEditModal({ visible: false, currentRow: null })

  const handlePreview = (record) => {
    setPreviewModal({ visible: true, currentRow: record, content: record.apiContent || '' })
  }

  const closePreviewModal = () => setPreviewModal({ visible: false, currentRow: null, content: '' })

  const handleToggleStatus = async (record) => {
    if (!record.dynamicKey && !record.keyValue) {
      showNotification('error', 'Action not allowed', 'No dynamic key available for this row')
      return
    }
    const dynamicKey = record.dynamicKey || record.key
    const payload = {
      display_name: record.display_name || record.label,
      content: record.apiContent || '',
      is_active: !record.is_active
    }
    setSaving(true)
    try {
      await axios.put(`${dynamicContentsUrl}edit/`, payload, {
        headers: getHeader(),
        params: { key: dynamicKey, product_key: productCode, package_code: packageCode }
      })
      showNotification('success', 'Success', 'Status updated successfully')
      fetchDynamicContents({ productCode, packageCode })
    } catch (e) {
      showNotification('error', 'Failed to update status', 'Please try again later')
    } finally {
      setSaving(false)
    }
  }

  const handleSave = async () => {
    const { displayName, keyValue, content, isActive, isCustomAdd } = modalForm
    const { currentRow } = editModal

    if (!displayName || !keyValue) {
      showNotification('error', 'Validation error', 'Display name and key are required')
      return
    }

    const isExisting = currentRow && currentRow.isDefined
    const payload = { display_name: displayName, key: keyValue, content, is_active: isActive }

    setSaving(true)
    try {
      if (isExisting && !isCustomAdd) {
        await axios.put(`${dynamicContentsUrl}edit/`,
          { display_name: displayName, content, is_active: isActive },
          { headers: getHeader(), params: { key: keyValue, product_key: productCode, package_code: packageCode } }
        )
      } else {
        await axios.post(dynamicContentsUrl, payload, {
          headers: getHeader(),
          params: { product_key: productCode, package_code: packageCode }
        })
      }
      showNotification('success', 'Success', 'Content saved successfully')
      closeEditModal()
      fetchDynamicContents({ productCode, packageCode })
    } catch (e) {
      showNotification('error', 'Failed to save content', 'Please try again later')
    } finally {
      setSaving(false)
    }
  }

  const { fetching, saving } = loadingState
  const { displayName, keyValue, content, isActive, isCustomAdd } = modalForm

  const editorPreviousContent = `<div class="template-content">${content || ''}</div>`

  const handleEditorUpdateContent = useCallback((value) => {
    const parser = new DOMParser()
    const parsed = parser.parseFromString(value, 'text/html')
    const inner = parsed.querySelector('.template-content')
    updateModalForm({ content: inner ? inner.innerHTML : value })
  }, [updateModalForm])

  const columns = [
    { title: 'Content', dataIndex: 'content', key: 'content' },
    { title: 'Status', dataIndex: 'status', key: 'status' },
    {
      title: 'Action',
      key: 'action',
      render: (_, record) => (
        <div>
          <Button type='link' onClick={() => handlePreview(record)}>Preview</Button>
          <Button type='link' onClick={() => openEditModal(record)}>Edit</Button>
          {!record.isDefined && (
            <Button type='link' onClick={() => openEditModal(record)}>Add</Button>
          )}
          {record.isDefined && (
            <Button type='link' onClick={() => handleToggleStatus(record)}>
              {record.is_active ? 'Deactivate' : 'Activate'}
            </Button>
          )}
        </div>
      )
    }
  ]

  return (
    <div className='product-configuration-tab'>
      <div style={{ display: 'flex', justifyContent: 'end', paddingRight: '40px', paddingBottom: '20px' }}>
        <Button type='primary' onClick={openAddCustomModal}>Add Custom Description</Button>
      </div>
      <TableWrapper
        columns={columns}
        dataSource={tableData}
        tableClassName='tableDesign'
        pagination={false}
        loading={fetching || saving}
      />

      <Modal
        title='Dynamic Content'
        visible={editModal.visible}
        onOk={handleSave}
        onCancel={closeEditModal}
        confirmLoading={saving}
        destroyOnClose
      >
        <div style={{ marginBottom: 12 }}>
          <span>Display Name</span>
          <Input
            value={displayName}
            onChange={(e) => updateModalForm({ displayName: e.target.value })}
            placeholder='Enter display name'
          />
        </div>
        <div style={{ marginBottom: 12 }}>
          <span>Key</span>
          <Input
            value={keyValue}
            onChange={(e) => updateModalForm({ keyValue: e.target.value })}
            placeholder='Enter unique key'
            disabled={editModal.currentRow && editModal.currentRow.isDefined && !isCustomAdd}
          />
        </div>
        <div style={{ marginBottom: 12 }}>
          <span>Content (HTML)</span>
          <TextEditor
            previousContent={editorPreviousContent}
            updateContent={handleEditorUpdateContent}
          />
        </div>
        <div>
          <span style={{ marginRight: 8 }}>Active</span>
          <Switch checked={isActive} onChange={(val) => updateModalForm({ isActive: val })} />
        </div>
      </Modal>

      <Modal
        title={get(previewModal.currentRow, 'display_name') || get(previewModal.currentRow, 'label') || 'Preview'}
        visible={previewModal.visible}
        onOk={closePreviewModal}
        onCancel={closePreviewModal}
        footer={[
          <Button key='close' type='primary' onClick={closePreviewModal}>Close</Button>
        ]}
        width={800}
      >
        <div
          className='ql-editor'
          dangerouslySetInnerHTML={{ __html: previewModal.content || '<p>No content defined yet.</p>' }}
        />
      </Modal>
    </div>
  )
}

export default ProductConfigurationSection
