import React, { Component } from 'react';
import TableWrapper from '../../../components/Table'
import { get } from 'lodash'
import { connect } from 'react-redux'
import tabActions from '../../../../../redux/productConfig/actions'
import { packageValidations } from '../../../constants/detailPageSections'
import { validationTableFormation } from '../commanFunction'

const {
  getPackagesValidation,
  resetProductConfigRedux
} = tabActions
class DataValidationSection extends Component {
  constructor (props) {
    super(props)
    this.state = {
      tableData: []
    }
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      section2Data,
      tableDataSource,
      tableDataSourceMessage
    } = nextProps
    if (tableDataSourceMessage === 'success') {
      this.setState({
        tableData: validationTableFormation(get(tableDataSource, 'data.details', []), section2Data)
      })
      this.props.resetProductConfigRedux(['getproductPackageValidationMessage'])
    }
  }

  componentDidMount () {
    const { productCode, packageCode } = this.props

    this.props.getPackagesValidation({
      query: {
        productCode: productCode,
        packageCode: packageCode
      }
    })
  }

  render () {
    const { tableData } = this.state
    const { tableDataSourceLoading, tableDataSourceError } = this.props
    return (
      <TableWrapper
        columns={packageValidations}
        dataSource={tableData}
        label='Data validation'
        tableClassName='tableDesign'
        tip='Data validation Loading...'
        pagination={false}
        loading={tableDataSourceLoading && !tableDataSourceError}
        cardClassName='section-2'
        tableAboveMessage='Policy creation Data'
      />
    )
  }
}

DataValidationSection.defaultProps = {
  tableDataSource: {}
}
export default connect(
  state => ({
    tableDataSource: state.ProductConfigurable.getproductPackageValidation,
    tableDataSourceMessage: state.ProductConfigurable.getproductPackageValidationMessage,
    tableDataSourceLoading: state.Loading.GET_PACKAGES_VALIDATION,
    tableDataSourceError: state.Error.GET_PACKAGES_VALIDATION
  }), {
    getPackagesValidation,
    resetProductConfigRedux
  }
)(DataValidationSection)
