import React, { useEffect } from 'react'
import { Row, Col, Button, Popover, notification } from 'antd'
import PropTypes from 'prop-types'
import {
  DraftWrapper,
  DraftPublished,
  PublishUndoCtn
} from './commanComponent.style'
import { connect } from 'react-redux'
import modalActions from '../../../redux/productConfig/actions'

const { getPublishUndoDraftDataRequest, resetProductConfigRedux } =
  modalActions

function DetailSection (data) {
  const {
    productData,
    cardClassName,
    showDraftData = false,
    detailData: {
      draft_data: draftData,
      code: packageCode = '',
      product_code: productCode = '',
      published_by: publishedBy = ''
    } = {},
    getPublishUndoDraftDataRequest,
    onHandleModalClose = () => {},
    pubLishUndoMessage,
    pubLishUndoStatusMessage,
    resetProductConfigRedux,
    profile: { email } = {}
  } = data

  const handlePublishUndoDraft = (status) => {
    const query = {
      productCode,
      packageCode,
      state: status
    }
    if (email) {
      const payload = { requested_by: email }
      getPublishUndoDraftDataRequest({ query, payload })
    }
  }

  useEffect(() => {
    if (pubLishUndoMessage) {
      if (pubLishUndoMessage === 'success') {
        notification.success({
          message: pubLishUndoStatusMessage || 'Package Updated Successfully'
        })
        onHandleModalClose()
      } else {
        notification.error({
          message: pubLishUndoStatusMessage || 'Error'
        })
      }
    }
    resetProductConfigRedux(['pubLishUndoMessage', 'pubLishUndoStatusMessage'])
  }, [pubLishUndoStatusMessage, pubLishUndoMessage])

  const content = (
    <PublishUndoCtn>
      <Button type='primary' onClick={() => handlePublishUndoDraft('undo')}>
        Undo
      </Button>
      <Button type='primary' onClick={() => handlePublishUndoDraft('publish')}>
        Publish
      </Button>
    </PublishUndoCtn>
  )

  return (
    <>
      {draftData && Object.keys(draftData).length && showDraftData
        ? (
          <Popover content={content} placement='right' trigger='click' getPopupContainer={trigger => trigger.parentElement}>
            <DraftWrapper>DRAFT</DraftWrapper>
          </Popover>
          )
        : null}
      <Row type='flex' justify='space-between'>
        {productData.map((element, index) => {
          return (
            <Col key={index} span={12} className='section-data'>
              <Row type='flex'>
                <Col span={cardClassName === 'section-1' ? 24 : 6}>
                  <h4>
                    <b>{element.label}</b>
                  </h4>
                </Col>
                <Col span={cardClassName === 'section-1' ? 24 : 10}>
                  <p>{element.value()}</p>
                </Col>
              </Row>
            </Col>
          )
        })}
      </Row>
      {showDraftData && publishedBy
        ? (
          <DraftPublished>
            <span className='bold'>Published By: </span> {publishedBy}
          </DraftPublished>
          )
        : null}
    </>
  )
}
DetailSection.defaultProps = {
  data: {
    productData: [],
    cardClassName: ''
  }
}
DetailSection.propTypes = {
  data: PropTypes.shape({
    productData: PropTypes.arrayOf(PropTypes.object),
    loading: PropTypes.bool
  })
}
export default connect(
  (state) => ({
    profile: state.Auth.profile,
    pubLishUndoStatusMessage:
      state.ProductConfigurable.pubLishUndoStatusMessage,
    pubLishUndoMessage: state.ProductConfigurable.pubLishUndoMessage
  }),
  {
    getPublishUndoDraftDataRequest,
    resetProductConfigRedux
  }
)(DetailSection)
