import React from 'react'
import PropTypes from 'prop-types'
import { Row, Col, Button, Card, Upload, Icon } from 'antd'
import styled from 'styled-components'
import { connect } from 'react-redux'


const ButtonSection = styled.div`
  display:flex;
  flex-direction: row;
  .ant-upload,
  .ant-btn: nth-child(1) {
    margin-right:${props => props.showSecondButton && '20px;'}
  }
`
const LabelSection = styled.div`
  display:flex;
  flex-direction: row;
  align-items: center;
  .label {
    margin-right:${props => props.showSecondButton && '20px;'}
  }
`
const dummyRequest = ({ file, onSuccess }) => {
  onSuccess()
}
class SectionWrapper extends React.Component {
  render () {
    const {
      cardClassName,
      loading,
      label,
      buttonName,
      buttonFunction,
      disabled,
      showSecondButton = false,
      secondButtonName,
      secondButtonFunction = null,
      showThirdButton = false,
      thirdButtonName,
      thirdButtonFunction = null,
      importPackageDataLoading
    } = this.props
    return (
      <Card className={cardClassName} loading={loading}>
        <Row type='flex' justify='space-between'>
          <Col>
            <LabelSection showThirdButton>
              <h3 className='label'><b>{label}</b></h3>
              {
                showThirdButton &&
                  <Button type='default' onClick={thirdButtonFunction}>{thirdButtonName}</Button>
              }
            </LabelSection>
          </Col>
          <Col>
            <ButtonSection showSecondButton>
              {
                (showSecondButton && !showThirdButton) &&
                  <Button type='default' onClick={secondButtonFunction}>{secondButtonName}</Button>
              }
              {
                (showSecondButton && showThirdButton) &&
                  <Upload
                    showUploadList={false}
                    customRequest={dummyRequest}
                    onChange={file => secondButtonFunction(file)}
                  >
                    <Button loading={importPackageDataLoading}> <Icon type='upload' />{secondButtonName}</Button>
                  </Upload>
              }
              <Button disabled={disabled} type='primary' onClick={buttonFunction}>{buttonName}</Button>
            </ButtonSection>
          </Col>
        </Row>
        <Row type='flex' justify='center' className='hearder-Block'>
          <Col span={24}>
            {this.props.children}
          </Col>
        </Row>
      </Card>
    )
  }
}

SectionWrapper.defaultProps = {
  cardClassName: '',
  loading: false,
  label: '',
  buttonName: '',
  disabled: false,
  importPackageDataLoading: false
}

SectionWrapper.propTypes = {
  cardClassName: PropTypes.string,
  loading: PropTypes.bool,
  label: PropTypes.string,
  buttonName: PropTypes.string,
  buttonFunction: PropTypes.func,
  disabled: PropTypes.bool
}

export default connect(
  state => ({
    importPackageDataLoading: state.Loading.IMPORT_PACKAGE,
  }), {}
)(SectionWrapper)
