import React from 'react'
import { Row, Col, Icon } from 'antd'
import { FilterInput, FilterInputSelectOption } from '../../../../components/tables/helperCells'
export function Section1Data (data) {
  const {
    code: productCode,
    name: productName,
    category_name: productCategory,
    created_at: createdAt,
    updated_at: updatedAt
  } = data
  return [
    {
      label: 'Product Code',
      value: () => productCode
    },
    {
      label: 'Created At',
      value: () => createdAt
    },
    {
      label: 'Product Name',
      value: () => productName
    },
    {
      label: 'Updated At',
      value: () => updatedAt
    },
    {
      label: 'Category',
      value: () => productCategory
    }
  ]
}

export function Section3DataTable (props) {
  const { searchText, filterProviderCode, providersList, filterPackageName } = this.state
  return [
    {
      title: 'Action',
      render: (val, record) => (
        <i
          className='far fa-eye'
          onClick={() => this.packageModal(val)}
          style={{
            cursor: 'pointer',
            textAlign: 'center'
          }}
        />
      )
    },
    {
      key: 'name',
      title: (
        <div className='table-heading-filter'>
          <span>Package Name</span>
        </div>
      ),
      dataIndex: 'name',
      filterDropdown: (
        <FilterInput
          idIdentifier='name_product_config'
          searchText={searchText?.name}
          onInputChange={(e) => this.handleOnInputQuery(e.target.value, 'name')}
          onSearch={(e) => this.handleOnSearchQuery(e, 'name')}
        />
      ),
      filterIcon: (
        <Icon
          className={`floatL fS-12 ${filterPackageName?.name ? 'active-class' : 'default'}`}
          type='filter'
          theme='outlined'
        />
      ),
      filterDropdownVisible: filterPackageName,
      sorter: true,
      sortDirections: ['descend'],
      onFilterDropdownVisibleChange: (visible) =>
        this.setState({ filterPackageName: visible })
    },
    {
      title: 'Provider',
      key: 'provider_code',
      dataIndex: 'provider_code',
      filterDropdown: (
        <FilterInputSelectOption
          placeholder='Select Provider'
          idIdentifier='provider_code_product_config'
          searchText={searchText?.provider_code}
          onInputChange={(e) => this.handleOnInputQuery(e, 'provider_code')}
          onSearch={(e) => this.handleOnSearchQuery(e, 'provider_code')}
          enableButton={searchText && searchText?.provider_code}
          optionData={providersList?.map(l => ({ id: l?.code, display_name: l?.name }))}
          isProduct
        />
      ),
      filterIcon: (
        <Icon
          className={`floatL fS-12 ${filterProviderCode?.provider_code ? 'active-class' : 'default'}`}
          type='filter'
          theme='outlined'
        />
      ),
      filterDropdownVisible: filterProviderCode,
      sorter: true,
      sortDirections: ['descend'],
      onFilterDropdownVisibleChange: (visible) =>
        this.setState({ filterProviderCode: visible })
    },
    {
      title: 'Policy no format',
      render: (val) => {
        const {
          policy_number_source: policySource,
          prefix_policy: prefixPolicy,
          number_of_digits_policy: noOfDigits,
          suffix_policy: suffixPolicy
        } = val
        return policySource === 'custom' ? `${prefixPolicy}${noOfDigits}${suffixPolicy}` : 'Application Number'
      }
    },
    {
      title: 'Start Date Time',
      render: (val) => {
        const {
          coverage_start_same_as_policy_creation: coveragestartDate,
          coverage_start_buffer_days: coverageBufferDays,
          coverage_start_derived_from_attribute: startAttributeId
        } = val
        if (coveragestartDate) {
          return 'Same as Policy Creation date'
        } else {
          return `${coverageBufferDays} days from ${startAttributeId}`
        }
      }
    },
    {
      title: 'End Date Time',
      render: (val) => {
        const {
          coverage_end_derived_from_attribute: endAttributeId,
          coverage_end_diff_days_from_coverage_start: endDateDays,
          coverage_end_diff_months_from_coverage_start: endDateMonth
        } = val

        if (endDateDays > 0) return `${endDateDays} days since start date`
        else if (endDateMonth > 0) return `${endDateMonth} months since start date`
        else {
          return `from ${endAttributeId}`
        }
      }
    },
    {
      title: 'Premium Calculation',
      render: (val) => {
        const {
          premium_type: premiumType
        } = val

        switch (premiumType) {
          case 'fixed':
            return 'Fixed'
          case 'mapped':
            return 'Map Based'
          case 'derived':
            return 'Derived'
          case 'ranged':
            return 'Range Based'
          case 'nested':
            return 'Nested'
          case 'hook':
            return 'Predefined'
          default:
            return 'Combined Premium Logic'
        }
      }
    }
  ]
}
// TODO: fixed the labels as per request
export function packageDetailSection (props) {
  const {
    code,
    provider_code: InsuranceProvider,
    send_policy_creation_failure_notification: sendMail,
    coverage_start_same_as_policy_creation: coveragestartDate,
    coverage_start_buffer_days: coverageBufferDays,
    coverage_start_derived_from_product_attribute: startAttributeId,
    coverage_end_derived_from_product_attribute: endAttributeId,
    coverage_end_diff_days_from_coverage_start: endDateDays,
    coverage_end_diff_months_from_coverage_start: endDateMonth,
    extra_info: extraInfo,
    premium_type: premiumType,
    premium_logic: premiumLogic,
    policy_number_source: policySource,
    prefix_policy: prefixPolicy,
    prefix_holder_name: prefixHolderName,
    number_of_digits_policy: noOfDigits,
    suffix_policy: suffixPolicy,
    has_termination_flow: terminationFlow,
    has_cancellation_flow: cancellationFlow,
    termination_flow_type: terminationType,
    cancellation_flow_type: cancellationType,
    recon_time_derived_from_product_attribute: reconTime,
    is_recon_time_derivable: reconDerived,
    has_blacklist_config: blackListConfig,
    has_endorsement_flow: endorsementFlow,
    is_fixed_policy_holder_name: isFixedPolicyHolderName,
    policy_expired_event_flag: policyExpiredEventFlag,
    use_policy_evaluation: usePolicyEvaluation,
    formula_expression: formulaExpression
  } = props.detailData.draft_data || props.detailData
  return [
    {
      label: 'Package Code',
      value: () => code
    },
    {
      label: 'Coverage start',
      value: () => {
        if (coveragestartDate) {
          return 'Same as Policy Creation date'
        } else {
          return `${coverageBufferDays} days from ${startAttributeId}`
        }
      }
    },
    {
      label: 'Insurance provider',
      value: () => {
        return InsuranceProvider || '-'
      }
    },
    {
      label: 'Coverage end',
      value: () => {
        if (endDateDays > 0) return `${endDateDays} days since start date`
        else if (endDateMonth > 0) return `${endDateMonth} months since start date`
        else {
          return `from ${endAttributeId}`
        }
      }
    },
    {
      label: 'Extra info',
      value: () => (
        <table>
          <thead>
            <tr>
              <th>Extra Info</th>
              <th>Prefix Holder Name</th>
              <th>Fixed Policy Holder Name</th>
              <th>Policy Expired Event Flag</th>
              <th>Use Policy Evaluation</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td>{extraInfo || '-'}</td>
              <td>{prefixHolderName || '-'}</td>
              <td>{isFixedPolicyHolderName || '-'}</td>
              <td>{policyExpiredEventFlag || '-'}</td>
              <td>{usePolicyEvaluation || '-'}</td>
            </tr>
          </tbody>
        </table>
      )
    },
    {
      label: 'Premium Calculation',
      value: () => {
        switch (premiumType) {
          case 'fixed': return `Fixed ${premiumLogic.value}`
          case 'derived': return `Derived - ${premiumLogic.value}% of ${premiumLogic.product_attribute_code}`
          case 'mapped': return (
            <table className='premium-table'>
              <thead>
                <tr>
                  <th className='premium-table-th'>Operand</th>
                  <th className='premium-table-th'>Value</th>
                </tr>
              </thead>
              <tbody>
                <tr>
                  {
                    premiumLogic.map((item, index) => {
                      return (
                        <React.Fragment key={index}>
                          <td className='premium-table-td'>{item.operand}</td>
                          <td className='premium-table-td'>{item.value}</td>
                        </React.Fragment>
                      )
                    })
                  }
                </tr>
              </tbody>
            </table>
          )
          case 'ranged': return (
            <table className='premium-table'>
              <thead>
                <tr>
                  <th className='premium-table-th'>Lower Operand</th>
                  <th className='premium-table-th'>Lower Operator</th>
                  <th className='premium-table-th'>Upper Operand</th>
                  <th className='premium-table-th'>Upper Operator</th>
                  <th className='premium-table-th'>Premium Value</th>
                </tr>
              </thead>
              <tbody>
                <tr>
                  {
                    premiumLogic.map((item, index) => {
                      return (
                        <React.Fragment key={index}>
                          <td className='premium-table-td'>{item.lower_operand}</td>
                          <td className='premium-table-td'>{item.lower_operator}</td>
                          <td className='premium-table-td'>{item.upper_operand}</td>
                          <td className='premium-table-td'>{item.upper_operator}</td>
                          <td className='premium-table-td'>{item.value}</td>
                        </React.Fragment>
                      )
                    })
                  }
                </tr>
              </tbody>
            </table>
          )
          case 'age':
            return 'Age Based Premium'
          case 'nested':
            return 'Nested Based Premium'
          case 'hook':
            return 'Predefined Function Based Premium'
          default:
            return 'Combined Based Premium'
        }
      }
    },
    {
      label: 'Send policy failure email',
      value: () => sendMail ? 'Yes' : 'No'
    },
    {
      label: "Custom (Premium V2)",
      value: () => formulaExpression || "-"
    },
    {
      label: 'Worker Type',
      value: () => {
        return (
          <>
            <Row type='flex' gutter={40}>
              <Col>Policy Number</Col>
              <Col>
                {
                  policySource === 'custom' ? `${prefixPolicy}${noOfDigits}${suffixPolicy}` : 'Application Number'
                }
              </Col>
            </Row>
            <Row type='flex' gutter={40}>
              <Col>Policy Document</Col>
              <Col> No</Col>
            </Row>
          </>
        )
      }
    },
    {
      label: 'Termination Flow',
      value: () => {
        if (terminationFlow) return `Yes - ${terminationType === 'with_refund' ? 'Termination with refund flow' : 'Termination without refund flow'}`
        else {
          return 'No'
        }
      }
    },
    {
      label: 'Cancellation Flow',
      value: () => {
        if (cancellationFlow) return `Yes - ${cancellationType === 'with_refund' ? 'Cancellation with refund flow' : 'Cancellation without refund flow'}`
        else {
          return 'No'
        }
      }
    },
    {
      label: 'Recon Time',
      value: () => {
        if (reconDerived) {
          return `Derived - ${reconTime}`
        } else {
          return 'False'
        }
      }
    },
    {
      label: 'Blacklist Config',
      value: () => {
        if (blackListConfig) {
          return 'True'
        } else {
          return 'False'
        }
      }
    },
    {
      label: 'Endorsement Flow',
      value: () => {
        if (endorsementFlow) {
          return 'True'
        } else {
          return 'False'
        }
      }
    }
  ]
}

export const packageValidations = [
  {
    title: 'Field Code',
    key: 'product_attribute_code',
    dataIndex: 'product_attribute_code'
  },
  {
    title: 'Validation',
    key: 'validations',
    dataIndex: 'validations',
    render: (record) => record.map(element => element.code).join(',')
  },
  {
    title: 'Value',
    render: (record) => record.validations.filter(item => item.value && item.value).map(item => item.value).join(',')
  }
]
