import React, { Component } from 'react'
import { Tabs } from 'antd'
import { get } from 'lodash'
import moment from 'moment'
import PropTypes from 'prop-types'
import DetailSection from '../../components/detailCardSection'
import { connect } from 'react-redux'
import { packageDetailSection } from '../../constants/detailPageSections'
import { ModalStyleWrapper, ModalDataBodyWrapper } from './index.style'
import modalActions from '../../../../redux/productConfig/actions'
import ModalWrapper from '../../components/Modal'
import HeaderWrapperSection from '../../components/SectionWrapper'
import ProviderSection from './ModalSections/providerSections'
import EndorsementSection from './ModalSections/endorsementSection'
import DataValidationSection from './ModalSections/dataValidationSection'
import AdditionalConfigurationPage from './ModalSections/additionalConfigurationSection'
import ProductConfigurationSection from './ModalSections/productConfigurationSection'

const { TabPane } = Tabs
const { resetProductConfigRedux } = modalActions
class PackageDetailModalWrapper extends Component {
  constructor (props) {
    super(props)
    this.state = {
      tableData: [],
      productAttributes: [],
      productCode: ''
      // packageCode: ''
    }
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { productDetailAttributesData, productDetailAttributesMessage } =
      nextProps
    if (productDetailAttributesMessage === 'success') {
      this.setState({
        productAttributes: get(productDetailAttributesData, 'data.details', [])
      })
    }
  }

  openEditPackageHandler = () => {
    this.props.editPackageInfo()
  };

  openEditDataValidationHandler = () => {
    this.props.editDataValidationFunction()
  };

  handleTabsChange = (key) => {
    this.props.tabChange(key)
  };

  draftUpdateContent = (draftChanges) => {
    return (
      <div className='draft_updates'>
        <div div className='draft_updates_title'>
          Draft Updates:
        </div>
        {Object.keys(draftChanges).map((draft, ind) => {
          return (
            <div key={ind}>
              - {draft}:&nbsp;
              <span className='draft_updates_text'>
                {draft === 'updated_at'
                  ? moment(draftChanges[draft].from)
                      .utc()
                      .format('YYYY-MM-DD HH:mm:ss')
                  : draftChanges[draft].from.toString()}
                <span>&#8594;</span>&nbsp;
                {draft === 'updated_at'
                  ? moment(draftChanges[draft].to)
                      .utc()
                      .format('YYYY-MM-DD HH:mm:ss')
                  : draftChanges[draft].to.toString()}
              </span>
            </div>
          )
        })}
      </div>
    )
  };

  render () {
    const visible = get(this.props, 'visible', false)
    const detailData = get(this.props, 'detailSection', {})
    const loading = get(this.props, 'loading', false)
    const { providerData, tabNo, section2Data, productCode } = this.props
    const packageCode = get(detailData, 'code')
    const draftChanges = get(detailData, 'draft_changes')

    return (
      <ModalStyleWrapper>
        <ModalWrapper
          title={get(detailData, 'name', '')}
          visible={visible}
          cancelSubmit={this.props.closeModel}
          width='1000px'
          footer={null}
          submitModal={null}
        >
          <ModalDataBodyWrapper>
            <Tabs
              type='card'
              onChange={this.handleTabsChange}
              activeKey={tabNo}
            >
              <TabPane tab='Package Details' key='1'>
                <div className='first-section'>
                  <HeaderWrapperSection
                    label=''
                    buttonName='Edit Package info'
                    loading={false}
                    buttonFunction={this.openEditPackageHandler}
                  >
                    <DetailSection
                      cardClassName='section-1'
                      productData={packageDetailSection.call(this, {
                        detailData,
                        providerData
                      })}
                      loading={loading}
                      showDraftData
                      detailData={detailData}
                      onHandleModalClose={this.props.onHandleModalClose}
                    />
                  </HeaderWrapperSection>
                </div>
                {draftChanges ? this.draftUpdateContent(draftChanges) : null}
              </TabPane>
              <TabPane tab='Data Validation' key='2'>
                <div className='second-section'>
                  <HeaderWrapperSection
                    label='Data Validations'
                    buttonName='Edit data Validations'
                    loading={false}
                    buttonFunction={this.openEditDataValidationHandler}
                  >
                    <DataValidationSection
                      productCode={productCode}
                      packageCode={packageCode}
                      section2Data={section2Data}
                    />
                  </HeaderWrapperSection>
                </div>
              </TabPane>
              <TabPane tab='Additional Configuration' key='3'>
                <div className='third-section'>
                  <AdditionalConfigurationPage
                    history={this.props.history}
                    section2Data={this.props.section2Data}
                    productCode={this.props.productCode}
                    packageData={detailData}
                  />
                </div>
              </TabPane>
              {(get(detailData, 'policy_number_source') === 'provider' ||
                get(detailData, 'document_generation_source') ===
                  'provider') && (
                    <TabPane tab='Provider Info' key='4'>
                      <ProviderSection
                        history={this.props.history}
                        section2Data={this.props.section2Data}
                        productCode={this.props.productCode}
                        packageData={detailData}
                      />
                    </TabPane>
              )}
              {get(detailData, 'has_endorsement_flow') && (
                <TabPane tab='Generic Endorsement' key='5'>
                  <EndorsementSection
                    history={this.props.history}
                    section2Data={this.props.section2Data}
                    productCode={this.props.productCode}
                    packageCode={get(detailData, 'code', '')}
                  />
                </TabPane>
              )}
              <TabPane tab='Product Description' key='6'>
                <ProductConfigurationSection
                  productCode={this.props.productCode}
                  packageCode={get(detailData, 'code', '')}
                />
              </TabPane>
            </Tabs>
          </ModalDataBodyWrapper>
        </ModalWrapper>
      </ModalStyleWrapper>
    )
  }
}
PackageDetailModalWrapper.defaultProps = {
  loading: false,
  productCode: '',
  visible: true,
  detailSection: {},
  tableDataSource: {
    data: {
      details: []
    },
    message: '',
    success: false
  },
  productDetailAttributes: {
    data: {
      details: []
    },
    message: '',
    success: false
  }
}
PackageDetailModalWrapper.propTypes = {
  productCode: PropTypes.string,
  detailSection: PropTypes.object,
  providerData: PropTypes.arrayOf(PropTypes.object),
  tableDataSource: PropTypes.shape({
    data: PropTypes.shape({
      details: PropTypes.arrayOf(PropTypes.object)
    }),
    message: PropTypes.string,
    success: PropTypes.bool
  }),
  productDetailAttributes: PropTypes.shape({
    data: PropTypes.shape({
      details: PropTypes.arrayOf(PropTypes.object)
    }),
    message: PropTypes.string,
    success: PropTypes.bool
  })
}
export default connect(
  (state) => ({
    productDetailAttributesData:
      state.ProductConfigurable.productDetailAttributes,
    productDetailAttributesMessage:
      state.ProductConfigurable.productDetailAttributesMessage
  }),
  {
    resetProductConfigRedux
  }
)(PackageDetailModalWrapper)
