import { StateProvider } from '../../WizardSteps/Step3PackageDetail/ProviderSection/context/attributeContext'
import Screen1 from '../../WizardSteps/Step3PackageDetail/ProviderSection/pages/Screen1'

export default function ProviderSections ({ ...props }) {
  const { productCode, packageData, section2Data, history } = props
  return (
    <ProviderDetailContextProvider>
      <StateProvider>
        <Row type='flex' justify='center'>
          <Col span={22}>
            <Screen1
              type='edit'
              step2={section2Data}
              history={history}
              provider={get(packageData, 'provider_code')}
              productCode={productCode}
              packageCode={get(packageData, 'code')}
            />
          </Col>
        </Row>
      </StateProvider>
    </ProviderDetailContextProvider>
  )
}
