export const tableFormation = (data, parentIndex = '') => {
  for (let i = 0; i < data.length; i++) {
    if (data[i].nested && data[i].nested.length > 0) {
      data[i] = {
        ...data[i],
        key: parentIndex ? parseInt(`${parentIndex}${i + 1}`) : i + 1,
        children: data[i].nested
      }
      tableFormation(data[i].nested, i + 1)
    } else {
      data[i] = {
        ...data[i],
        key: parentIndex ? parseInt(`${parentIndex}${i + 1}`) : i + 1
      }
    }
  }
  return data
}

export function validationTableFormation (validationTable, section2Data) {
  function traverse (data) {
    return data.length > 0 && data.map(item => {
      if (!('children' in item)) {
        const newItem = validationTable.find(ele => ele.product_attribute_id === item.id)
        return newItem
      } else {
        let newItem = validationTable.find(ele => ele.product_attribute_id === item.id)
        newItem = {
          ...newItem,
          nested: [...traverse(item.children)],
          children: [...traverse(item.children)]
        }
        return newItem
      }
    })
  }
  return tableFormation(traverse(section2Data))
}
