/* eslint-disable react-hooks/exhaustive-deps */
import { useState, useEffect, useContext } from 'react'
import { get } from 'lodash'
import { Row, Col, Form, Select, Button, notification, Spin } from 'antd'
import StyledContainer from './index.style'
import { useLoaderContextValue } from '../../../../../../../../../globalContextProvider/LoaderContext'
import { useResetState, useApiVersionList, useProviderCredentialData, useApiCredentialValue } from '../../hooks/useProviderDetails'
import { store } from '../../context/attributeContext'
import { getFormItems } from './formField'
const { Option } = Select

const FormDataFields = ({ ...props }) => {
  const { form, provider = '', productCode, packageCode, collapseHandler, functionName = '', versionList, dynamicFieldData = [] } = props
  const [versionListState, setVersionList] = useState([])
  const [functionNameState, setFunctionName] = useState('')
  const { state, dispatch } = useContext(store)
  const [{ providerCredentialData, providerCredentialStatus }, providerCredentialRequest] = useProviderCredentialData()
  const [{ apiCredentialValueData, apiCredentialValueStatus }, apiCredentialRequest] = useApiCredentialValue()
  const [providerDynamicData, setproviderDynamicData] = useState([])
  const [{ apiVersionData, apiVersionStatus }, apiVersionListRequest] = useApiVersionList()
  const { getFieldDecorator, validateFields } = form
  const [{ API_CREDENTIAL_VALUE_LOADER = false, PROVIDER_CREDENTIAL_LOADER }] = useLoaderContextValue()
  const [resetProviderDetailsState] = useResetState()

  useEffect(() => {
    if (apiVersionStatus === 'success') {
      setproviderDynamicData(get(apiVersionData, 'data.details.attributes', []))
      dispatch({
        type: 'update-api-version-data',
        payload: get(apiVersionData, 'data.details.attributes', [])
      })
      resetProviderDetailsState(['apiVersionStatus', 'apiVersionData'])
    }
    if (apiCredentialValueStatus === 'success') {
      setproviderDynamicData(get(apiCredentialValueData, 'data.details.attributes', []))
      resetProviderDetailsState(['apiCredentialValueStatus'])
    }
    if (providerCredentialStatus === 'success') {
      notification.success({
        message: get(providerCredentialData, 'message', '')
      })
      collapseHandler()
      resetProviderDetailsState(['providerCredentialStatus'])
    }
    if (providerCredentialStatus !== 'success' && providerCredentialStatus !== undefined) {
      notification.error({
        message: get(providerCredentialData, 'message', '')
      })
      resetProviderDetailsState(['providerCredentialStatus'])
    }
  }, [apiVersionData, providerCredentialStatus, apiCredentialValueStatus])

  useEffect(() => {
    setproviderDynamicData(dynamicFieldData)
  }, [dynamicFieldData])

  useEffect(() => {
    const funName = functionName || get(state, 'functionName')
    if (functionName) {
      apiVersionListRequest({
        query: {
          provider_code: provider,
          function_name: funName,
          attributeType: 'credential'
        }
      })
      apiCredentialRequest({
        query: {
          provider_code: provider,
          function_name: funName,
          product_code: productCode,
          package_code: packageCode
        }
      })
      setFunctionName(funName)
    }
  }, [functionName, productCode, packageCode])

  useEffect(() => {
    setVersionList(versionList)
  }, [versionList])

  function onChange (value) {
    setFunctionName(value)
    dispatch({
      type: 'set-function-name',
      payload: value
    })
    apiVersionListRequest({
      query: {
        provider_code: provider,
        function_name: value,
        attributeType: 'credential'
      }
    })
  }

  const handleSubmit = (e) => {
    e.preventDefault()
    validateFields((err, values) => {
      if (!err) {
        const bodyPayload = providerDynamicData.map((item) => {
          return {
            provider_attribute_id: item.id,
            value: values[item.code]
          }
        })
        dispatch({
          type: 'update-api-version-data',
          payload: providerDynamicData.map((item) => {
            return {
              ...item,
              value: values[item.code]
            }
          })
        })
        providerCredentialRequest({
          query: {
            provider_code: provider,
            function_name: functionNameState,
            product_code: productCode,
            package_code: packageCode
          },
          body: bodyPayload
        })
      }
    })
  }
  return (
    <Form onSubmit={handleSubmit}>
      <StyledContainer>
        <Row type='flex' justify='center'>
          <Col>
            <div className='select__style_screen_1'>
              <p><b>Provider</b>:&nbsp;{provider}</p>
            </div>
          </Col>
        </Row>
        <Row type='flex' justify='center'>
          <Col span={10}>
            <div className='credential__section_1'>
              <p>API Version</p>
              <Select
                showSearch
                onChange={onChange}
                value={functionNameState}
                optionFilterProp='children'
                filterOption={(input, option) =>
                  option.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
              >
                {
                  versionListState.map((item, index) => <Option key={index} value={item.function_name}>{item.function_name}</Option>)
                }
              </Select>
            </div>
          </Col>
          <Col span={20}>
            <Spin spinning={API_CREDENTIAL_VALUE_LOADER}>
              <Row type='flex' justify='center'>
                {
                  providerDynamicData.length > 0 &&
                  providerDynamicData.map((item, index) => {
                    return (
                      <Col span={18} key={index}>
                        {
                          getFormItems.call(this, {
                            getFieldDecorator,
                            formName: item.code,
                            disableField: false,
                            type: item.type,
                            label: item.name,
                            initialValue: item.value,
                            required: item.is_mandatory,
                            message: `${item.code} is required`
                          })
                        }
                      </Col>
                    )
                  })
                }
              </Row>
            </Spin>
          </Col>
          {
            providerDynamicData.length > 0 &&
              <Col span={20}>
                <div className='button__style_sction_1'>
                  <Button loading={PROVIDER_CREDENTIAL_LOADER} htmlType='submit' type='primary'>Submit</Button>
                </div>
              </Col>
          }
        </Row>
      </StyledContainer>
    </Form>
  )
}

const WrappedFormComponent = Form.create()(FormDataFields)

export default WrappedFormComponent
