import React, { useState, useEffect } from 'react'
import { Select, Table, Button, Modal, notification } from 'antd'
import { connect } from 'react-redux'
import actions from '../../../../../redux/productConfig/actions'
import { capitalizeFirstLetter } from '../../../../../../helpers/utility'
import { useHistory } from 'react-router'
import { showNotification } from '../../../../../../components/ShowNotification'

const { Option } = Select
const { confirm } = Modal

const AdditionalConfigurationSection = (props) => {
  const history = useHistory()

  const [availableOptions, setAvailableOptions] = useState([])
  const [configListDetails, setConfigListDetails] = useState([])
  const [selectedTypes, setSelectedTypes] = useState([])
  const [tableData, setTableData] = useState({})
  const [selectedSlugMap, setSelectedSlugMap] = useState({})
  const [addonFilters, setAddonFilters] = useState({})
  const [addonData, setAddonData] = useState({})

  useEffect(() => {
    if (props?.productConfigSlugs?.details?.length > 0) {
      const slugsInA = new Set(
        configListDetails.map((item) => item.config_slug)
      )
      const filteredB = props.productConfigSlugs.details.filter(
        (item) => !slugsInA.has(item.code)
      )
      const options =
        filteredB.length > 0 ? filteredB.map((item) => item.code) : []
      setAvailableOptions(options)
    }
  }, [props.productConfigSlugs, configListDetails])

  useEffect(() => {
    if (props?.productConfigList?.details) {
      const details = props.productConfigList.details
      const uniqueSlugs = [...new Set(details.map((item) => item.config_slug))]
      const slugMap = {}
      details.forEach((item) => {
        if (item.config_slug && item.config_reference_id) {
          slugMap[item.config_slug] = { ...item }
        }
      })

      const initialTableData = {}
      const initialFilters = {}

      uniqueSlugs.forEach((slug) => {
        initialTableData[slug] = []
        if (slugMap[slug]) {
          initialFilters[slug] = {
            limit: 5,
            offset: 0,
            addon_map_id: slugMap[slug]?.config_reference_id
          }
        }
      })

      setConfigListDetails(details)
      setSelectedTypes(uniqueSlugs)
      setTableData(initialTableData)
      setSelectedSlugMap(slugMap)
      setAddonFilters(initialFilters)
      props.getProductConfigSlugListActions({
        query: { limit: 100, offset: 0 }
      })
    }
  }, [props.productConfigList])

  useEffect(() => {
    if (props?.packageData?.product_code && props?.packageData?.code) {
      getProductConfigList()
    }
  }, [props?.packageData])

  useEffect(() => {
    Object.entries(addonFilters).forEach(([type, filter]) => {
      if (filter?.addon_map_id != null) {
        props.getListAddonsActions({
          query: filter,
          meta: { configSlug: type }
        })
      }
    })
  }, [addonFilters])

  useEffect(() => {
    if (
      props?.listAddonsData?.details?.details?.length > 0 &&
      props?.listAddonsData?.configSlug
    ) {
      const configSlug = props.listAddonsData.configSlug
      const response = props.listAddonsData

      setAddonData((prev) => ({
        ...prev,
        [configSlug]: response
      }))

      const items = response.details.details.map((item, index) => ({
        key: `${configSlug}-${item.id}`,
        no: index + 1 + (response.metadata.offset || 0),
        code: item.code,
        mandatory: item.auto_apply,
        allowZeroResult: item.allow_zero_result,
        isActive: item.is_active,
        raw: item
      }))

      setTableData((prev) => ({
        ...prev,
        [configSlug]: items
      }))
    }
  }, [props.listAddonsData])

  useEffect(() => {
    if (props.updatePackageConfigstatusMessage === 'success') {
      showNotification(
        'success',
        'Update Success',
        'Deactivate status updated successfully!'
      )
      getProductConfigList()
    } else if (props.updatePackageConfigstatusMessage === 'error') {
      showNotification('error', 'Update Failed', 'Something Went Wrong!')
    }
  }, [props.updatePackageConfigstatusMessage])

  useEffect(() => {
    if (props.addPackageConfigMessage === 'success') {
      showNotification('success', 'Success', 'Configuration Attached!')
      getProductConfigList()
    } else if (props.addPackageConfigMessage === 'error') {
      showNotification('error', 'Error', 'Something Went Wrong!')
    }
  }, [props.addPackageConfigMessage])

  const getProductConfigList = () => {
    props.getProductConfigListActions({
      query: {
        limit: 100,
        offset: 0,
        product_code: props?.packageData?.product_code,
        package_code: props?.packageData?.code
      }
    })
  }

  const handleSelectChange = (value) => {
    if (
      !value ||
      !props?.packageData?.code ||
      !props?.packageData?.product_code
    ) {
      notification.error('Something Went Wrong!')
      return
    }

    props.addPackageConfigActions({
      query: {
        product_code: props?.packageData?.product_code,
        package_code: props?.packageData?.code
      },
      body: { code: value }
    })
  }

  const handleToggleDeactivationStatus = (slugMap, type) => {
    const selectedtable = slugMap[type]
    const warningMsg = slugMap[type]?.deactivated
      ? `Are you sure you want to Activate ${type}?`
      : `Are you sure you want to Deactivate ${type}? All data will be lost.`
    confirm({
      title: warningMsg,
      onOk () {
        const payload = [
          {
            config_id: selectedtable?.ID,
            deactivated: !selectedtable?.deactivated
          }
        ]
        props.updatePackageConfigActions({
          query: {
            product_code: props?.packageData?.product_code,
            package_code: props?.packageData?.code
          },
          body: payload
        })
      }
    })
  }

  const generateColumns = (type) => [
    { title: 'No', dataIndex: 'no', key: 'no' },
    { title: capitalizeFirstLetter(type), dataIndex: 'code', key: 'code' },
    {
      title: 'Mandatory Status',
      dataIndex: 'mandatory',
      key: 'mandatory',
      render: (mandatory) => (mandatory ? 'Yes' : 'No')
    },
    {
      title: 'Allow Zero Result',
      dataIndex: 'allow_zero_result',
      key: 'allow_zero_result',
      render: (_, record) => (record.allowZeroResult ? 'Yes' : 'No')
    },
    {
      title: 'Status',
      key: 'is_active',
      render: (_, record) =>
        record.isActive
          ? (
            <span style={{ color: 'green' }}>Active</span>
            )
          : (
            <span style={{ color: 'red' }}>Inactive</span>
            )
    },
    {
      title: 'Actions',
      key: 'actions',
      render: (_, record) => (
        <div>
          <Button
            type='link'
            size='small'
            onClick={() => {
              history.push({
                pathname: `add-ons-config/edit/${record?.raw?.id}`,
                state: {
                  step2: props.section2Data,
                  config_slug: type,
                  config_reference_id:
                    selectedSlugMap[type]?.config_reference_id,
                  product_code: props.productCode,
                  package_code: props.packageData?.code
                }
              })
            }}
          >
            Edit
          </Button>
        </div>
      )
    }
  ]

  return (
    <div style={{ padding: '24px' }}>
      <h2>Data Validation Configuration</h2>

      {availableOptions.length > 0
        ? (
          <Select
            placeholder='Choose type'
            style={{ width: 200 }}
            onChange={handleSelectChange}
            value={undefined}
            loading={props.addPackageConfigLoading}
            disabled={props.addPackageConfigLoading}
          >
            {availableOptions.map((opt) => (
              <Option key={opt} value={opt}>
                {opt}
              </Option>
            ))}
          </Select>
          )
        : (
          <p>No configuration types available.</p>
          )}

      {(selectedTypes || []).map((type) => {
        const filter = addonFilters[type] || {}
        const metadata = addonData[type]?.metadata || {}
        return (
          <div
            key={type}
            style={{
              marginBottom: 32,
              borderTop: '1px solid #eee',
              paddingTop: 16
            }}
          >
            <h3>
              {type}{' '}
              <Button
                type='dashed'
                size='small'
                danger
                onClick={() =>
                  handleToggleDeactivationStatus(selectedSlugMap, type)}
                style={{ marginLeft: 12 }}
              >
                {selectedSlugMap[type]?.deactivated ? 'Activate' : 'Deactivate'}
              </Button>
            </h3>
            {!selectedSlugMap[type]?.deactivated && (
              <Button
                type='primary'
                onClick={() => {
                  const configReferenceId =
                    selectedSlugMap[type]?.config_reference_id
                  history.push({
                    pathname: 'add-ons-config/add',
                    state: {
                      step2: props.section2Data,
                      config_slug: type,
                      config_reference_id: configReferenceId,
                      product_code: props.productCode,
                      package_code: props.packageData?.code
                    }
                  })
                }}
                style={{ marginBottom: 16 }}
              >
                Add New
              </Button>
            )}
            {!selectedSlugMap[type]?.deactivated
              ? (
                <Table
                  columns={generateColumns(type)}
                  dataSource={tableData[type] || []}
                  pagination={{
                    current:
                    filter.offset != null
                      ? Math.floor(filter.offset / (filter.limit || 5)) + 1
                      : 1,
                    pageSize: filter.limit || 5,
                    total: metadata.count || 0,
                    showSizeChanger: true,
                    pageSizeOptions: ['5', '10', '20', '50', '100']
                  }}
                  onChange={(pagination) => {
                    const newLimit = pagination.pageSize
                    const newOffset = (pagination.current - 1) * newLimit
                    setAddonFilters((prev) => ({
                      ...prev,
                      [type]: {
                        ...prev[type],
                        limit: newLimit,
                        offset: newOffset
                      }
                    }))
                  }}
                  rowKey='key'
                  locale={{
                    emptyText: 'No data. Click "Add New" to create entries.'
                  }}
                />
                )
              : (
                <p>Product Config is Deactivated.</p>
                )}
          </div>
        )
      })}
    </div>
  )
}

const mapStateToProps = (state) => {
  return {
    productConfigSlugs:
      state.ProductConfigurable?.getAllProductConfigSlugData || [],
    getProductConfigSlugMessage:
      state.ProductConfigurable?.getAllProductConfigSlugMessage || '',
    addPackageConfigData: state.ProductConfigurable?.addPackageConfigData || [],
    addPackageConfigMessage:
      state.ProductConfigurable?.addPackageConfigMessage || '',
    addPackageConfigLoading: state.Loading.ADD_PACKAGE_CONFIG,
    productConfigList: state.ProductConfigurable?.getAllProductConfigData || [],
    getProductConfigListMessage:
      state.ProductConfigurable?.getAllProductConfigMessage || '',
    listAddonsData: state.ProductConfigurable?.getListAddonsData || {},
    listAddonsMessage: state.ProductConfigurable?.getListAddonsMessage || '',
    updatePackageConfigstatusData:
      state.ProductConfigurable?.updatePackageConfigstatusData || {},
    updatePackageConfigstatusMessage:
      state.ProductConfigurable?.updatePackageConfigstatusMessage || ''
  }
}

const mapDispatchToProps = (dispatch) => {
  return {
    getProductConfigSlugListActions: (payload) =>
      dispatch({ type: actions.GET_PRODUCT_CONFIG_SLUG_LIST_REQUEST, payload }),
    addPackageConfigActions: (payload) =>
      dispatch({ type: actions.ADD_PACKAGE_CONFIG_REQUEST, payload }),
    getProductConfigListActions: (payload) =>
      dispatch({ type: actions.GET_PRODUCT_CONFIG_LIST_REQUEST, payload }),
    getListAddonsActions: (payload) =>
      dispatch({
        type: actions.GET_LIST_ADDONS_REQUEST,
        payload,
        meta: payload.meta
      }),
    updatePackageConfigActions: (payload) =>
      dispatch({ type: actions.UPDATE_PACKAGE_CONFIG_STATUS_REQUEST, payload }),
    resetProductConfigRedux: (payload) =>
      dispatch({ type: actions.RESET_PRODUCT_CONFIG, payload })
  }
}

export default connect(
  mapStateToProps,
  mapDispatchToProps
)(AdditionalConfigurationSection)
