import { Quill } from 'react-quill'
import QuillBetterTable from 'quill-better-table'

import 'react-quill/dist/quill.snow.css'
import 'quill-better-table/dist/quill-better-table.css'

const Font = Quill.import('formats/font')
Font.whitelist = ['Muli']
Quill.register(Font, true)

const BaseImage = Quill.import('formats/image')
class CustomImage extends BaseImage {
  static create (value) {
    const imageValue =
      value && typeof value === 'object' ? value.url : value
    const node = super.create(imageValue)

    if (value && typeof value === 'object') {
      const { width, height } = value
      if (width) {
        node.setAttribute('width', width)
        node.style.width = `${width}px`
      }
      if (height) {
        node.setAttribute('height', height)
        node.style.height = `${height}px`
      }
    }

    return node
  }

  static formats (domNode) {
    const formats = {}
    if (domNode.hasAttribute('width')) {
      formats.width = domNode.getAttribute('width')
    }
    if (domNode.hasAttribute('height')) {
      formats.height = domNode.getAttribute('height')
    }
    return formats
  }

  format (name, value) {
    if (name === 'width' || name === 'height') {
      if (value) {
        this.domNode.setAttribute(name, value)
        this.domNode.style[name] = `${value}px`
      } else {
        this.domNode.removeAttribute(name)
        this.domNode.style[name] = ''
      }
      return
    }
    super.format(name, value)
  }
}

Quill.register(CustomImage, true)

QuillBetterTable.register()

Quill.register(
  {
    'modules/better-table': QuillBetterTable
  },
  true
)

const TEXT_EDITOR_FORMATS = [
  'header',
  'font',
  'size',
  'bold',
  'italic',
  'underline',
  'strike',
  'blockquote',
  'list',
  'indent',
  'align',
  'link',
  'image',
  'background',
  'color',
  'table-col',
  'table-cell-line',
  'table-cell',
  'table-row',
  'table'
]

const icons = Quill.import('ui/icons')
icons.insertTable = `
  <svg viewBox="0 0 18 18" xmlns="http://www.w3.org/2000/svg">
    <rect class="ql-stroke" height="12" width="12" x="3" y="3" rx="1"/>
    <line class="ql-stroke" x1="3" y1="9" x2="15" y2="9"/>
    <line class="ql-stroke" x1="9" y1="3" x2="9" y2="15"/>
  </svg>
`

function getTextEditorModules ({ setPendingImageFile, setIsModalVisible, message }) {
  return {
    table: false,
    clipboard: {
      matchVisual: false
    },
    keyboard: {
      bindings: QuillBetterTable.keyboardBindings
    },
    toolbar: {
      container: [
        [{ header: [1, 2, 3, 4, 5, 6, false] }],
        [{ align: [] }],
        ['bold', 'italic', 'underline'],
        [
          { list: 'ordered' },
          { list: 'bullet' },
          { color: ['#000000a6', 'custom-color'] },
          'link',
          'image',
          'insertTable'
        ]
      ],
      handlers: {
        color: function (value) {
          if (value === 'custom-color') {
            value = window.prompt('Enter Hex Color Code')
          }
          this.quill.format('color', value)
        },
        image: () => {
          const input = document.createElement('input')
          input.setAttribute('type', 'file')
          input.setAttribute('accept', 'image/*')
          input.click()

          input.onchange = async () => {
            const file = input.files[0]
            if (file && /^image\//.test(file.type)) {
              setPendingImageFile(file)
              setIsModalVisible(true)
            } else {
              message.error('You could only upload images.')
            }
          }
        },
        insertTable: function () {
          const tableModule = this.quill.getModule('better-table')
          if (tableModule) {
            tableModule.insertTable(3, 3)
          }
        }
      }
    },
    'better-table': {
      operationMenu: {
        items: {
          unmergeCells: {
            text: 'Unmerge cells'
          }
        }
      }
    }
  }
}

export { TEXT_EDITOR_FORMATS, getTextEditorModules }
